sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float amount;
uniform float radius;
uniform float aspect;
uniform float feather;
uniform float bias;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 ctr = center * size;
    float2 e = float2(aspect, 1.0) * radius * length(size) * 0.5;
    float2 q = (coord - ctr) / e;
    float r = length(q);
    float p = 1.0 + amount * 1.5 * bias;
    float rp = pow(max(r, 0.0001), p);
    float inside = 1.0 - smoothstep(1.0 - feather, 1.0, r);
    float nr = mix(r, rp, inside);
    float2 q2 = q / max(r, 0.0001) * nr;
    return fin(c, tex(ctr + q2 * e), opacity);
}
